using AcxiomCRM.Web.Data; using AcxiomCRM.Web.Models; using AcxiomCRM.Web.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize] public class CustomersController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;readonly AuditService audit;public CustomersController(ApplicationDbContext d,UserManager<ApplicationUser> u,AuditService a){db=d;um=u;audit=a;}
 string U=>um.GetUserId(User)!; bool Priv=>User.IsInRole("Admin")||User.IsInRole("Manager");
 public async Task<IActionResult> Index(string? q){var x=db.Customers.Include(c=>c.Owner).AsQueryable();if(!Priv)x=x.Where(c=>c.OwnerId==U);if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.CustomerName.Contains(q)||c.Email.Contains(q)||c.Phone.Contains(q)||c.CompanyName.Contains(q));return View(await x.OrderByDescending(c=>c.CreatedAt).ToListAsync());}
 public IActionResult Create()=>View(new CustomerVm());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(CustomerVm vm){if(!ModelState.IsValid)return View(vm);if(await db.Customers.AnyAsync(c=>c.Email==vm.Email||c.Phone==vm.Phone)){ModelState.AddModelError("","A customer with this email or phone already exists.");return View(vm);}var c=new Customer{CustomerCode="CUS-"+Random.Shared.Next(100000,999999),CustomerName=vm.CustomerName.Trim(),Email=vm.Email.Trim().ToLower(),Phone=vm.Phone,CompanyName=vm.CompanyName,Address=vm.Address,City=vm.City,State=vm.State,Status=vm.Status,OwnerId=Priv&&vm.OwnerId!=null?vm.OwnerId:U};db.Customers.Add(c);await db.SaveChangesAsync();await audit.LogAsync("CREATE","Customer",c.Id.ToString(),null,c.CustomerName,U);return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Edit(int id){var c=await db.Customers.FindAsync(id);if(c==null)return NotFound();if(!Priv&&c.OwnerId!=U)return Forbid();return View(new CustomerVm{Id=c.Id,CustomerName=c.CustomerName,Email=c.Email,Phone=c.Phone,CompanyName=c.CompanyName,Address=c.Address,City=c.City,State=c.State,Status=c.Status,OwnerId=c.OwnerId});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,CustomerVm vm){var c=await db.Customers.FindAsync(id);if(c==null)return NotFound();if(!Priv&&c.OwnerId!=U)return Forbid();if(!ModelState.IsValid)return View(vm);if(await db.Customers.AnyAsync(x=>x.Id!=id&&(x.Email==vm.Email||x.Phone==vm.Phone))){ModelState.AddModelError("","Email or phone already belongs to another customer.");return View(vm);}var old=$"{c.CustomerName}|{c.Email}|{c.Phone}|{c.Status}";c.CustomerName=vm.CustomerName.Trim();c.Email=vm.Email.Trim().ToLower();c.Phone=vm.Phone;c.CompanyName=vm.CompanyName;c.Address=vm.Address;c.City=vm.City;c.State=vm.State;c.Status=vm.Status;c.ModifiedAt=DateTime.UtcNow;if(Priv&&vm.OwnerId!=null)c.OwnerId=vm.OwnerId;await db.SaveChangesAsync();await audit.LogAsync("UPDATE","Customer",id.ToString(),old,$"{c.CustomerName}|{c.Email}|{c.Phone}|{c.Status}",U);return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var c=await db.Customers.FindAsync(id);if(c==null)return NotFound();if(!Priv&&c.OwnerId!=U)return Forbid();c.Status=CustomerStatus.Inactive;c.ModifiedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync("DEACTIVATE","Customer",id.ToString(),null,"Inactive",U);return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Details(int id){var c=await db.Customers.Include(x=>x.Owner).Include(x=>x.Opportunities).Include(x=>x.Leads).FirstOrDefaultAsync(x=>x.Id==id);if(c==null)return NotFound();if(!Priv&&c.OwnerId!=U)return Forbid();return View(c);}
}
